class Solution {
public:
    int maximumMatchingIndices(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size(), answer = 0;
        for (int shift = 0; shift < n; ++shift) {
            int matches = 0;
            for (int i = 0; i < n; ++i) {
                if (nums1[i] == nums2[(i - shift + n) % n]) ++matches;
            }
            answer = max(answer, matches);
        }
        return answer;
    }
};
